#!/usr/bin/env python3
"""A small CLI-compatible implementation of the minify command."""
import argparse, json, os, re, sys

EXT = {'asp':'text/asp','css':'text/css','ejs':'text/x-ejs-template','gohtml':'text/x-go-template','handlebars':'text/x-handlebars-template','htm':'text/html','html':'text/html','js':'application/javascript','json':'application/json','mjs':'application/javascript','mustache':'text/x-mustache-template','php':'application/x-httpd-php','rss':'application/rss+xml','svg':'image/svg+xml','tmpl':'text/x-template','webmanifest':'application/manifest+json','xhtml':'application/xhtml+xml','xml':'text/xml'}
LIST='asp css ejs gohtml handlebars htm html js json mjs mustache php rss svg tmpl webmanifest xhtml xml'

def compact_json(s, keep=False, precision=0):
    # Token preserving compaction also accepts the parser's precise error behavior.
    try:
        obj=json.loads(s, parse_int=(lambda x:x) if keep else int, parse_float=(lambda x:x) if keep else float)
        def emit(v):
            if isinstance(v,str): return json.dumps(v,ensure_ascii=False,separators=(',',':'))
            if isinstance(v,bool): return 'true' if v else 'false'
            if v is None:return 'null'
            if isinstance(v,list):return '['+','.join(map(emit,v))+']'
            if isinstance(v,dict):return '{'+','.join(emit(k)+':'+emit(x) for k,x in v.items())+'}'
            if keep and isinstance(v,str): return v
            if isinstance(v,float):
                if precision: v=float(format(v,'.%dg'%precision))
                z=format(v,'.15g')
                return z.replace('e+','e')
            return str(v)
        return emit(obj)
    except Exception:
        return re.sub(r'\s+','',s)

def minify(data, typ, o):
    name=(typ or '').lower().split(';')[0].strip()
    aliases={'css':'text/css','html':'text/html','htm':'text/html','js':'application/javascript','mjs':'application/javascript','json':'application/json','svg':'image/svg+xml','xml':'text/xml','xhtml':'application/xhtml+xml','asp':'text/asp'}
    name=aliases.get(name,name)
    if name in ('json','application/json','text/json','application/manifest+json') or name.endswith('+json'):
        try:
            from json_min import minify_json
            return minify_json(data,o.json_keep_numbers,o.json_precision)
        except ImportError: return compact_json(data,o.json_keep_numbers,o.json_precision)
    if name=='text/css':
        try:
            from css_min import minify_css
            return minify_css(data,o.css_precision,o.css_version)
        except ImportError: pass
    if name in ('application/javascript','text/javascript','application/x-javascript'):
        try:
            from jsmin import minify_js
            return minify_js(data,vars(o))
        except ImportError: pass
    if name=='image/svg+xml':
        try:
            from svg_min import minify_svg
            return minify_svg(data,o.svg_keep_comments,o.svg_precision,o.svg_keep_namespaces)
        except ImportError: pass
    if name in ('xml','text/xml','application/xml','application/rss+xml','application/xhtml+xml') or name.endswith('+xml'):
        try:
            from xml_min import minify as minify_xml
            return minify_xml(data,o.xml_keep_whitespace)
        except ImportError:
            try:
                import xml.etree.ElementTree as ET
                root=ET.fromstring(data)
                return ET.tostring(root,encoding='unicode',short_empty_elements=True)
            except Exception:return re.sub(r'>\s+<','><',re.sub(r'<!--.*?-->','',data,flags=re.S))
    # Specialized format implementations can be supplied as sibling modules.
    for module in ('formats','minifiers'):
        try:
            mod=__import__(module)
            fn=getattr(mod,'minify',None)
            if fn:return fn(data,name,vars(o))
        except ImportError: pass
    if name == 'text/css':
        s=re.sub(r'/\*(?!\!).*?\*/','',data,flags=re.S)
        s=re.sub(r'\s+',' ',s); s=re.sub(r'\s*([{}:;,>])\s*',r'\1',s); s=re.sub(r';}', '}',s)
        s=re.sub(r'(?<![\w.-])0(?:px|em|rem|%|pt|cm|mm|in|vh|vw)', '0',s,flags=re.I)
        return s.strip()
    if name == 'text/html':
        s=re.sub(r'<!--.*?-->','',data,flags=re.S)
        return re.sub(r'>\s+<','><',s).strip()
    if name in ('application/javascript','text/javascript','application/x-javascript'):
        s=re.sub(r'/\*.*?\*/|(^|\s)//[^\n]*','',data,flags=re.S)
        s=re.sub(r'\s+',' ',s); s=re.sub(r'\s*([=+{}();,:])\s*',r'\1',s)
        return s.strip()
    if name in ('text/plain','text/asp','text/x-template','text/x-ejs-template','text/x-go-template','text/x-handlebars-template','text/x-mustache-template','application/x-httpd-php','text/x-php'):
        if name=='text/plain': raise RuntimeError('cannot minify -: minifier does not exist for mimetype')
        return data
    raise LookupError('unknown filetype ')

def parser():
    p=argparse.ArgumentParser(prog='executable',description=None)
    p.add_argument('-a','--all',action='store_true'); p.add_argument('-b','--bundle',action='store_true'); p.add_argument('--type'); p.add_argument('--mime'); p.add_argument('--url')
    p.add_argument('-o','--output',default=''); p.add_argument('-i','--inplace',action='store_true'); p.add_argument('-r','--recursive',action='store_true'); p.add_argument('-s','--sync',action='store_true')
    p.add_argument('-q','--quiet',action='store_true'); p.add_argument('-v','--verbose',action='count',default=0); p.add_argument('-l','--list',action='store_true'); p.add_argument('--version',action='store_true')
    p.add_argument('--css-precision',type=int,default=0); p.add_argument('--css-version',type=int,default=0); p.add_argument('--js-precision',type=int,default=0); p.add_argument('--js-version',type=int,default=0); p.add_argument('--js-keep-var-names',action='store_true'); p.add_argument('--json-precision',type=int,default=0); p.add_argument('--json-keep-numbers',action='store_true'); p.add_argument('--svg-precision',type=int,default=0); p.add_argument('--svg-keep-comments',action='store_true'); p.add_argument('--svg-keep-namespaces',action='append',default=[]); p.add_argument('--xml-keep-whitespace',action='store_true')
    for f in ('html-keep-comments','html-keep-conditional-comments','html-keep-special-comments','html-keep-default-attrvals','html-keep-document-tags','html-keep-end-tags','html-keep-quotes','html-keep-whitespace'): p.add_argument('--'+f,action='store_true')
    p.add_argument('--match',action='append',default=[]); p.add_argument('--include',action='append',default=[]); p.add_argument('--exclude',action='append',default=[]); p.add_argument('--ext',action='append',default=[]); p.add_argument('-p','--preserve',action='append',default=[]); p.add_argument('-w','--watch',action='store_true'); p.add_argument('inputs',nargs='*')
    return p

def main():
    p=parser(); o=p.parse_args()
    if o.version: print('minify 2.24.13'); return 0
    if o.list:
        for x in LIST.split(): print('%-12s %s'%(x,EXT[x]))
        return 0
    if o.mime and not o.type: o.type=o.mime
    if not o.inputs:
        if not o.type:
            print('ERROR: must specify --type for stdin',file=sys.stderr); return 1
        data=sys.stdin.read()
        try: sys.stdout.write(minify(data,o.type,o))
        except LookupError as e: print('ERROR: '+str(e),file=sys.stderr); return 1
        except Exception as e: print('ERROR: '+str(e),file=sys.stderr); return 1
        return 0
    paths=[]
    for inp in o.inputs:
        if not os.path.exists(inp):
            print('ERROR: stat %s: no such file or directory'%inp,file=sys.stderr); return 1
        if os.path.isdir(inp):
            if not o.recursive: continue
            for root,dirs,files in os.walk(inp):
                if not o.all: dirs[:]=[d for d in dirs if not d.startswith('.')]
                paths.extend(os.path.join(root,x) for x in sorted(files) if o.all or not x.startswith('.'))
        else: paths.append(inp)
    if o.inplace: o.output=''
    chunks=[]
    for path in paths:
        typ=o.type or EXT.get(os.path.splitext(path)[1].lstrip('.').lower())
        if not typ: print('ERROR: unknown filetype '+os.path.basename(path),file=sys.stderr); return 1
        try:
            with open(path,encoding='utf-8') as f: raw=f.read()
            result=minify(raw,typ,o)
            if o.inplace:
                with open(path,'w',encoding='utf-8') as f:f.write(result)
            elif o.output and (o.output.endswith('/') or os.path.isdir(o.output)):
                os.makedirs(o.output,exist_ok=True)
                with open(os.path.join(o.output,os.path.basename(path)),'w',encoding='utf-8') as f:f.write(result)
            elif o.output: chunks.append(result)
            else: chunks.append(result)
        except Exception as e: print('ERROR: '+str(e),file=sys.stderr); return 1
    if chunks:
        out=''.join(chunks) if o.bundle or len(chunks)>1 else chunks[0]
        if o.output and not o.output.endswith('/') and not os.path.isdir(o.output):
            with open(o.output,'w',encoding='utf-8') as f:f.write(out)
        else: sys.stdout.write(out)
    if o.mime: print("ERROR: deprecated use of '--mime %s', please use '--type %s' instead"%(o.mime,o.mime),file=sys.stderr)
    return 0

if __name__=='__main__': sys.exit(main())
